import Foundation

/// Detects whether a pull request author is an agent.
struct AgentDetector {
    let registry: AgentRegistry

    func detect(author: Actor, branchName: String, commitTrailers: [String]) -> ActorKind {
        if let identity = registry.match(login: author.login, branch: branchName, trailers: commitTrailers) {
            return .agent(identity)
        }
        if author.kind == .bot { return .bot }
        return .human
    }
}
